//go:build amd64

package per

import (
	"github.com/thebagchi/asn1c-go/lib/cpu"
)

// How much input each assembly kernel handles per iteration: bytes in when
// encoding, characters in when decoding.
const (
	BIN_ENCODE_BLOCK        = 8
	BIN_DECODE_BLOCK        = 64
	BIN_SSE2_ENCODE_BLOCK   = 4
	BIN_SSE2_DECODE_BLOCK   = 32
	BIN_AVX512_ENCODE_BLOCK = 16
	BIN_AVX512_DECODE_BLOCK = 128
)

// The kernels are generated by avo from gen/bin.go into bin_amd64.s, with what
// every family shares in gen/main.go. The declarations at the end of this file
// are what Go sees of them, and go vet's asmdecl check holds them and the
// assembly's frames in step. Regenerate with "make generate".
//
//go:generate go run ./gen -only bin -out bin_amd64.s -pkg per

// The amd64 kernels. SSE2 is part of the architecture's baseline, so it can
// always run.
var (
	BIN_SSE2 = &_Kernel{
		name:        NAME_SSE2,
		have:        true,
		encodeBlock: BIN_SSE2_ENCODE_BLOCK,
		decodeBlock: BIN_SSE2_DECODE_BLOCK,
		encode:      _BinaryEncodeSSE2,
		decode:      _BinaryDecodeSSE2,
	}
	BIN_AVX2 = &_Kernel{
		name:        NAME_AVX2,
		have:        cpu.HAS_AVX2,
		encodeBlock: BIN_ENCODE_BLOCK,
		decodeBlock: BIN_DECODE_BLOCK,
		encode:      _BinaryEncodeAVX2,
		decode:      _BinaryDecodeAVX2,
	}
	BIN_AVX512 = &_Kernel{
		name:        NAME_AVX512,
		have:        cpu.HAS_AVX512,
		encodeBlock: BIN_AVX512_ENCODE_BLOCK,
		decodeBlock: BIN_AVX512_DECODE_BLOCK,
		encode:      _BinaryEncodeAVX512,
		decode:      _BinaryDecodeAVX512,
	}
)

// _BinKernels lists every kernel amd64 has, narrowest first.
//
// Revisions:
//   - 2026-09-24 01:40: initial creation
//   - 2026-10-21 21:35: the SSE2 kernel, between Go and AVX2 (review P31)
//   - 2026-10-21 23:56: the AVX-512 kernel, after AVX2 (review P33)
func _BinKernels() []*_Kernel {
	return []*_Kernel{
		BIN_GO,
		BIN_SSE2,
		BIN_AVX2,
		BIN_AVX512,
	}
}

// _EncodeBinary renders whole blocks of src with the assembly kernels, widest
// first: AVX2 when init selected it, then SSE2 over a block it left. It returns
// how many bytes it took; the caller finishes with the Go kernel, and kernel.go
// says why. The kernels are called by name for the reason bitbuffer._RunShift
// gives, and the AVX2 kernel ends in VZEROUPPER before the SSE2 one runs.
//
// Revisions:
//   - 2026-09-23 08:40: initial creation
//   - 2026-09-24 01:40: finishes with the Go kernel, and dispatches on the
//     kernel init selected
//   - 2026-09-24 02:00: the assembly kernel only, again; the Go kernel moved
//     to the caller
//   - 2026-10-21 21:35: the SSE2 kernel takes what AVX2 leaves, and all of it on a
//     machine with no AVX2 (review P31)
//   - 2026-10-21 23:56: the AVX-512 kernel first, then AVX2 on what is left (review P33)
func _EncodeBinary(
	dst,
	src []byte,
) int {
	var (
		done int
		wide = cpu.HAS_AVX2 && BIN_KERNEL != BIN_SSE2 && BIN_KERNEL != BIN_GO
	)

	if BIN_KERNEL == BIN_AVX512 {
		done = _BinaryEncodeAVX512(
			dst,
			src,
		)
	}

	if rest := src[done:]; wide && len(rest) >= BIN_ENCODE_BLOCK {
		done += _BinaryEncodeAVX2(
			dst[done*BITS_PER_BYTE:],
			rest,
		)
	}

	if rest := src[done:]; len(rest) >= BIN_SSE2_ENCODE_BLOCK {
		done += _BinaryEncodeSSE2(
			dst[done*BITS_PER_BYTE:],
			rest,
		)
	}

	return done
}

// _DecodeBinary parses whole blocks of src with the assembly kernels, AVX2 then
// SSE2 as _EncodeBinary does, stopping at the first block holding a character
// that is neither '0' nor '1', and returns how many characters it took; the
// caller finishes with the Go kernel.
//
// Revisions:
//   - 2026-09-23 08:40: initial creation
//   - 2026-09-24 01:40: finishes with the Go kernel, and dispatches on the
//     kernel init selected
//   - 2026-09-24 02:00: the assembly kernel only, again; the Go kernel moved
//     to the caller
//   - 2026-10-21 21:35: the SSE2 kernel takes what AVX2 leaves, and all of it on a
//     machine with no AVX2 (review P31)
//   - 2026-10-21 23:56: the AVX-512 kernel first, then AVX2 on what is left (review P33)
func _DecodeBinary(
	dst,
	src []byte,
) int {
	var (
		done int
		wide = cpu.HAS_AVX2 && BIN_KERNEL != BIN_SSE2 && BIN_KERNEL != BIN_GO
	)

	if BIN_KERNEL == BIN_AVX512 {
		done = _BinaryDecodeAVX512(
			dst,
			src,
		)
	}

	if rest := src[done:]; wide && len(rest) >= BIN_DECODE_BLOCK {
		done += _BinaryDecodeAVX2(
			dst[done/BITS_PER_BYTE:],
			rest,
		)
	}

	if rest := src[done:]; len(rest) >= BIN_SSE2_DECODE_BLOCK {
		done += _BinaryDecodeSSE2(
			dst[done/BITS_PER_BYTE:],
			rest,
		)
	}

	return done
}

// _BinaryEncodeAVX2 renders src as '0' and '1' characters into dst, leading bit
// first, eight bytes per iteration, and returns how many bytes it consumed: a
// multiple of eight. len(dst) must be at least 8*len(src). Declared noescape
// so a caller's stack buffer stays where it is; the same holds below.
//
// Revisions:
//   - 2026-09-23 09:10: initial creation, in place of the generated stub
//
//go:noescape
func _BinaryEncodeAVX2(
	dst,
	src []byte,
) int

// _BinaryDecodeAVX2 parses '0' and '1' characters from src into bytes in dst,
// leading character first, sixty-four characters per iteration, and returns
// how many characters it consumed: a multiple of sixty-four, short of len(src)
// when a block holds a character that is neither. len(dst) must be at least
// len(src)/8.
//
// Revisions:
//   - 2026-09-23 09:10: initial creation, in place of the generated stub
//
//go:noescape
func _BinaryDecodeAVX2(
	dst,
	src []byte,
) int

// _BinaryEncodeSSE2 is _BinaryEncodeAVX2 at four bytes per iteration, with SSE2
// only: it returns a multiple of four.
//
// Revisions:
//   - 2026-10-21 21:35: initial creation (review P31)
//
//go:noescape
func _BinaryEncodeSSE2(
	dst,
	src []byte,
) int

// _BinaryDecodeSSE2 is _BinaryDecodeAVX2 at thirty-two characters per iteration,
// with SSE2 only: it returns a multiple of thirty-two.
//
// Revisions:
//   - 2026-10-21 21:35: initial creation (review P31)
//
//go:noescape
func _BinaryDecodeSSE2(
	dst,
	src []byte,
) int

// _BinaryEncodeAVX512 is _BinaryEncodeAVX2 at sixteen bytes per iteration, in EVEX
// encodings only: it returns a multiple of sixteen. It needs AVX512BW.
//
// Revisions:
//   - 2026-10-21 23:56: initial creation (review P33)
//
//go:noescape
func _BinaryEncodeAVX512(
	dst,
	src []byte,
) int

// _BinaryDecodeAVX512 is _BinaryDecodeAVX2 at one hundred and twenty-eight characters
// per iteration, in EVEX encodings only: it returns a multiple of one hundred and
// twenty-eight. It needs AVX512BW.
//
// Revisions:
//   - 2026-10-21 23:56: initial creation (review P33)
//
//go:noescape
func _BinaryDecodeAVX512(
	dst,
	src []byte,
) int
